$function getImgList(){
    var str = html.match(/murl_e=\"(.*?)\"/)[1];
    var list = window.atob(str).split("\$qingtiandy\$");
    var cur = html.match(/qTcms_Cur=\"\/mh\/(\d+)\/(\d+)\.html\"/);
    var piclist = new Array([list.length]);
    for (var i = 0; i < list.length; i++) {
        var ts = new Date().getTime();
        var head = list[i];
   //     if(head.indexOf('baidu1')!=-1){
//head = list[i].replace(/http:\/\/www.baidu1.com/,"");
//}
        piclist[i] = "https://api.733.so/newfile.php?data=" + window.btoa(head+"|"+ts.toString()+"|"+cur[1]+"|"+cur[2]+"|"+"pc");
    }
    return piclist;
}@Header:{Referer:none}

$function getImgList(){
