 var piclist = new Array([path.length]);
var host=(/pageImage = "https:\/\/(.*?)\/images\//.exec(html)||[])[1];//res.xiaoqinre.com
 for (var i = 0; i < path.length; i++) {
 piclist[i] = "https://"+host+"/"+chapterPath + path[i];
 }
 return piclist;
}

