function xiutan(html,url,key,callBack){
    var host=(/http[s]*:\/\/([\d,\w,\-,\_,\.]+)\//.exec(url)||[])[1];
    html=html.replace(/<script(.*?)src\s*=\s*(["|']?)http(s?):/g,'<scr'+'ipt$1xsrc=$2http$3:');
    html=html.replace(/<link(.*?)href\s*=/g,'<link$1xhref=');
    html=html.replace(/<img(.*?)src\s*=/g,'<img$1xsrc=');
    html=html.replace(/<iframe(.*?)src\s*=/g,'<iframe$1xsrc=');
    html=html.replace('/js/common.js','');
    html=html.replace(/\/g_dd\/(.*?).js/g,'');
    html=html.replace(/\ssrc="http(s*)/,' xsrc="http$1');
    //html=html.replace(/<img id="image"/g,'<img xid="image"');
    var iframeSrcdoc='<base href="'+url+'" />\n'+html;
//+'\n<scr'+'ipt>var cih=(window.getCirh||window.getCih||window.getCih1||function(){})();if(cih) window.chapterImageHost = cih;</scr'+'ipt>';
console.log(iframeSrcdoc);
    var iframe=document.querySelector('iframe[id="evalIframe"]');
    if(iframe) iframe.remove();
    var iframe=document.createElement('iframe');
    iframe.id="evalIframe";
    iframe.sandbox="allow-scripts allow-same-origin";
    iframe.srcdoc="";
    window.evalIframeCallBack=function(rs){
        callBack(rs);
        iframe.remove();
        delete window.evalIframeCallBack;
    }
    iframe.onload=function(){

        iframe.contentWindow.document.write(iframeSrcdoc+'\n<scr'+'ipt>setTimeout(function(){parent.evalIframeCallBack('+key+')},1000)</scr'+'ipt>');
        // alert(document.querySelector('iframe[id="evalIframe"]').contentWindow.chapterImageHost)


    }
    document.body.appendChild(iframe);
}

