xiutan(result,baseUrl,"(function(){try{return (document.querySelector('img#image')||document.querySelectorAll('#images img[style*=\"display:block\"]')[document.querySelectorAll('#images img[style*=\"display:block\"]').length-1]||document.querySelectorAll('#images img')[1]||document.querySelector('#images img')||document.querySelectorAll('a:not([style*=\"none\"])>div:not([style*=\"none\"])>img[style*=\"block\"]')[0]).src}catch(e){console.error(e)}})()",function(url){

if(!url){
reject(url);
return;
}
   var path = result.match(/chapterImage\s*=\s*"(.*?)"/)[1];
resolve(url/* + path*/);
